'use strict';

const fs = require('node:fs');

const compromised = [];
let lockCount = 0;

function record(event) {
  if (process.env.PI_AGENT_LOCK_COMPROMISE_LOG) {
    fs.appendFileSync(
      process.env.PI_AGENT_LOCK_COMPROMISE_LOG,
      `${JSON.stringify({ event })}\n`,
    );
  }
}

async function lock(_targetPath, options = {}) {
  const index = lockCount;
  const name = index === 0 ? 'integration' : 'settings';
  lockCount += 1;
  compromised[index] = options.onCompromised;
  record(`${name}-acquired`);
  if (
    process.env.PI_AGENT_LOCK_COMPROMISE_PROBE === 'settings-before-recovery' &&
    index === 1
  ) {
    record('settings-compromised');
    options.onCompromised(new Error('settings lock compromised by test probe'));
  }
  return async () => record(`${name}-release`);
}

function compromise(index) {
  record(`${index === 0 ? 'integration' : 'settings'}-compromised`);
  compromised[index]?.(new Error('integration lock compromised by test probe'));
}

module.exports = { compromise, lock };
